// Construye el reporte de observabilidad (Execution Log) del agente
const out = $input.first().json;
const steps = out.intermediateSteps || [];
const pregunta = $('Chat Trigger').first().json.chatInput || '(sin mensaje)';
const sessionId = $('Chat Trigger').first().json.sessionId || 'n/d';
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

let filas = '';
steps.forEach((s, i) => {
  const a = s.action || {};
  const obs = typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation);
  filas += `<tr><td>${i + 1}</td><td><b>${esc(a.tool)}</b></td>` +
           `<td><pre>${esc(JSON.stringify(a.toolInput))}</pre></td>` +
           `<td><pre>${esc((a.log || '').slice(0, 800))}</pre></td>` +
           `<td><pre>${esc((obs || '').slice(0, 1500))}</pre></td></tr>`;
});
if (!filas) filas = '<tr><td colspan="5">El agente respondió sin usar herramientas.</td></tr>';

const html = `<h2>Log de ejecución – Agente de Triaje Comercial - Quirino Bebidas</h2>
<p><b>Fecha:</b> ${new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' })}<br>
<b>Sesión:</b> ${esc(sessionId)}<br>
<b>Herramientas usadas:</b> ${steps.length} (límite de iteraciones: 7)</p>
<h3>Mensaje del cliente</h3><blockquote>${esc(pregunta)}</blockquote>
<h3>Recorrido del razonamiento (ciclo ReAct)</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse;font-size:12px">
<tr style="background:#eee"><th>#</th><th>Tool</th><th>Input</th><th>Razonamiento</th><th>Resultado (observation)</th></tr>
${filas}</table>
<h3>Respuesta final del agente</h3><blockquote>${esc(out.output).replace(/\n/g,'<br>')}</blockquote>`;

return [{ json: {
  output: out.output,
  pregunta,
  sessionId,
  herramientasUsadas: steps.length,
  asunto: `[Log Agente] ${steps.length} tool(s) | ${pregunta.slice(0, 60)}`,
  html
} }];
